const baseUrl = (import.meta.env.VITE_API_BASE_URL || '/api').replace(/\/$/, '');

/** Posts a contact inquiry without exposing server SMTP settings to the browser. */
export async function sendContact(message) {
  const response = await fetch(`${baseUrl}/contact`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(message), signal: AbortSignal.timeout(20000) });
  const result = await response.json();
  if (!response.ok) { const error = new Error('Unable to send contact message.'); error.code = result.error?.code; throw error; }
  return result;
}